import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().execute();
    }

    void execute() {
        InputReader in = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        Problem solver = new Problem();
        solver.process(1, in, writer);
        writer.flush();
        writer.close();
    }

    static class Problem {
        private static final long MOD = 1000000007L;
        private static final long BIG = (long)1e18 + 1;
        private long[][] binom = new long[100][100];

        private long ways(long base, int n1, int k1, int n2, int k2) {
            base = (base * binom[n1][k1]) % MOD;
            base = (base * binom[n2][k2]) % MOD;
            return base;
        }

        void process(int testId, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int limit = in.nextInt();
            int count50 = 0, count100 = 0;
            for (int i = 0; i < N; i++) {
                int val = in.nextInt();
                if (val == 50) count50++;
                else count100++;
            }

            // Pascal's triangle
            for (int i = 0; i < 100; i++) {
                binom[i][0] = binom[i][i] = 1;
                for (int j = 1; j < i; j++) {
                    binom[i][j] = (binom[i-1][j] + binom[i-1][j-1]) % MOD;
                }
            }

            long[][][] minSteps = new long[200][200][2];
            long[][][] pathCount = new long[200][200][2];
            for (int i = 0; i < 200; i++) {
                for (int j = 0; j < 200; j++) {
                    Arrays.fill(minSteps[i][j], BIG);
                    Arrays.fill(pathCount[i][j], 0);
                }
            }

            minSteps[0][0][0] = 0;
            pathCount[0][0][0] = 1;

            Queue<Node> bfs = new LinkedList<>();
            bfs.offer(new Node(0, 0, 0, 0));

            while (!bfs.isEmpty()) {
                Node node = bfs.poll();
                int a = node.a;
                int b = node.b;
                int side = node.side;
                long steps = minSteps[a][b][side];

                if (side == 0) {
                    int left50 = count50 - a;
                    int left100 = count100 - b;
                    for (int take50 = 0; take50 <= left50; take50++) {
                        for (int take100 = 0; take100 <= left100; take100++) {
                            if (take50 == 0 && take100 == 0) continue;
                            int totalWeight = take50 * 50 + take100 * 100;
                            if (totalWeight > limit) break;
                            int na = a + take50;
                            int nb = b + take100;
                            int nextSide = side ^ 1;
                            if (minSteps[na][nb][nextSide] >= steps + 1) {
                                if (minSteps[na][nb][nextSide] > steps + 1) {
                                    minSteps[na][nb][nextSide] = steps + 1;
                                    bfs.offer(new Node(na, nb, nextSide, steps + 1));
                                    pathCount[na][nb][nextSide] = (pathCount[na][nb][nextSide] + ways(pathCount[a][b][side], left50, take50, left100, take100)) % MOD;
                                } else {
                                    pathCount[na][nb][nextSide] = (pathCount[na][nb][nextSide] + ways(pathCount[a][b][side], left50, take50, left100, take100)) % MOD;
                                }
                            }
                        }
                    }
                } else {
                    int left50 = a;
                    int left100 = b;
                    for (int take50 = 0; take50 <= left50; take50++) {
                        for (int take100 = 0; take100 <= left100; take100++) {
                            if (take50 == 0 && take100 == 0) continue;
                            int totalWeight = take50 * 50 + take100 * 100;
                            if (totalWeight > limit) break;
                            int na = a - take50;
                            int nb = b - take100;
                            int nextSide = side ^ 1;
                            if (minSteps[na][nb][nextSide] >= steps + 1) {
                                if (minSteps[na][nb][nextSide] > steps + 1) {
                                    minSteps[na][nb][nextSide] = steps + 1;
                                    bfs.offer(new Node(na, nb, nextSide, steps + 1));
                                    pathCount[na][nb][nextSide] = (pathCount[na][nb][nextSide] + ways(pathCount[a][b][side], left50, take50, left100, take100)) % MOD;
                                } else {
                                    pathCount[na][nb][nextSide] = (pathCount[na][nb][nextSide] + ways(pathCount[a][b][side], left50, take50, left100, take100)) % MOD;
                                }
                            }
                        }
                    }
                }
            }

            if (minSteps[count50][count100][1] == BIG) {
                out.println(-1);
            } else {
                out.println(minSteps[count50][count100][1]);
            }
            out.println(pathCount[count50][count100][1]);
        }

        static class Node {
            int a, b, side;
            long dist;
            Node(int a, int b, int side, long dist) {
                this.a = a;
                this.b = b;
                this.side = side;
                this.dist = dist;
            }
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buf = new byte[1024];
        private int p = 0, len = 0;

        public InputReader(InputStream stream) {
            in = stream;
        }

        private int nextByte() {
            if (len == -1) throw new IllegalStateException();
            if (p >= len) {
                p = 0;
                try { len = in.read(buf); } catch (IOException e) { throw new IllegalStateException(); }
                if (len <= 0) return -1;
            }
            return buf[p++];
        }

        public int nextInt() {
            int c;
            while ((c = nextByte()) <= ' ') {}
            int val = 0;
            do {
                val = val * 10 + (c - '0');
            } while ((c = nextByte()) > ' ');
            return val;
        }
    }
}
